import {build} from 'vite';
import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const hash=x=>createHash('sha256').update(x).digest('hex');
const lock=JSON.parse(readFileSync('package-lock.json'));
const keys=Object.keys(lock.packages).filter(Boolean).sort((a,b)=>b.length-a.length);
const result=await build({build:{write:false},logLevel:'silent'});
const packages=new Map(), assets={}, generated=new Map(), vendored=new Set();
let renderedModules=0;
for(const item of result.output){
 const content=item.type==='chunk'?item.code:item.source;
 assets[item.fileName]={bytes:Buffer.byteLength(content),sha256:hash(content)};
 assert.equal(assets[item.fileName].sha256,hash(readFileSync('dist/'+item.fileName)));
 if(item.type!=='chunk')continue;
 for(const [id,info] of Object.entries(item.modules)){
  if(!info.renderedLength)continue;
  renderedModules++;
  const index=id.indexOf('/node_modules/');if(index<0)continue;
  const local=id.slice(index+1).split('?')[0];
  const owner=keys.find(k=>local.startsWith(k+'/'));
  assert.ok(owner,local);
  const entry=packages.get(owner)||{path:owner,version:lock.packages[owner].version,license:lock.packages[owner].license,modules:0,renderedBytes:0};
  entry.modules++;entry.renderedBytes+=info.renderedLength;packages.set(owner,entry);
  if(local.slice(owner.length).includes('/node_modules/'))vendored.add(local);
  if(/node_modules\/@(?:hashgraph|hiero-ledger)\/proto\/(?:src|lib)\/proto.js$/.test(local)){
   generated.set(local,{path:local,sha256:hash(readFileSync(id.split('?')[0])),renderedBytes:info.renderedLength});
  }
 }
}
const before=JSON.parse(readFileSync(process.env.SOURCE_REPO+'/docs/evidence/007-t01a-protobuf-rebuild-restored-bundle.json')).packages;
const old=new Map(before.map(x=>[x.path,x]));
const now=[...packages.values()].sort((a,b)=>a.path.localeCompare(b.path));
const changes=[];
for(const path of new Set([...old.keys(),...packages.keys()])){
 const a=old.get(path),b=packages.get(path);
 if(!a||!b||a.version!==b.version)changes.push({path,before:a?.version??null,after:b?.version??null});
}
writeFileSync('/tmp/decoder014-sdk-bundle.json',JSON.stringify({lockSha256:hash(readFileSync('package-lock.json')),assets,renderedModules,packages:now,vendoredFiles:[...vendored],generatedSources:[...generated.values()],changesFrom007:changes},null,2)+'\n');
console.log(JSON.stringify({packages:now.length,generated:[...generated.values()],changes,assetsMatch:true}));

