import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {writeFileSync} from 'node:fs';
const require=createRequire('/home/outsider/.npm/_npx/6bcb61ec6d5aea22/node_modules/playwright/package.json');
const {chromium}=require('playwright');
const browser=await chromium.launch({executablePath:'/usr/bin/google-chrome',headless:true});
const results=[];
try {
  for (const [server,port] of [['dev',5173],['preview',4173]]) {
    for (const [device,viewport] of [['desktop',{width:1440,height:1000}],['mobile',{width:390,height:844}]]) {
      const origin=`http://127.0.0.1:${port}`;
      const context=await browser.newContext({viewport,serviceWorkers:'block'});
      const externalOrigins=[],errors=[];
      await context.route('**/*',route=>{
        const target=new URL(route.request().url());
        if(target.origin!==origin){externalOrigins.push(target.origin);return route.abort()}
        return route.continue();
      });
      await context.routeWebSocket('**/*',ws=>{
        if(new URL(ws.url()).origin===`ws://127.0.0.1:${port}`)ws.connectToServer();
        else{externalOrigins.push(new URL(ws.url()).origin);ws.close()}
      });
      const page=await context.newPage();
      page.on('pageerror',error=>errors.push(error.name));
      page.on('console',message=>{if(message.type()==='error')errors.push('console error')});
      await page.goto(origin,{waitUntil:'networkidle'});
      assert.equal(await page.getByRole('heading',{name:'HoldBook',exact:true}).count(),1);
      assert.equal(await page.getByText('Wallet not connected. Press Connect to begin.',{exact:true}).count(),1);
      assert.equal(await page.getByRole('button',{name:'Check deployment and config',exact:true}).isEnabled(),true);
      assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
      await page.keyboard.press('Tab');
      assert.equal(await page.evaluate(()=>document.activeElement.textContent),'Skip to content');
      assert.notEqual(await page.evaluate(()=>getComputedStyle(document.activeElement).outlineStyle),'none');
      await page.reload({waitUntil:'networkidle'});
      assert.equal(await page.getByText('Wallet not connected. Press Connect to begin.',{exact:true}).count(),1);
      assert.deepEqual(externalOrigins,[]);assert.deepEqual(errors,[]);
      results.push({server,device,viewport,idleAndReload:'passed',keyboardAndFocus:'passed',overflow:false,externalOrigins,errors});
      await context.close();
    }
  }
  writeFileSync('/tmp/decoder014-main-browser.json',JSON.stringify({browser:browser.version(),playwright:require('playwright/package.json').version,results},null,2)+'\n');
  console.log('4/4 idle application browser checks passed');
} finally {await browser.close()}
